<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import RawModelJsonValue from './RawModelJsonValue.vue';
import { modelMessageCards, modelPayloadSections, parseModelPayload } from './raw-model-payload';
const props = defineProps<{ text: string; contentType: string; title: string; complete?: boolean }>();
const mode = ref<'structured' | 'raw'>('structured'); const visible = ref(30); const copyStatus = ref(''); const copying = ref(false);
const parsed = computed(() => parseModelPayload(props.text, props.contentType));
const sections = computed(() => parsed.value.kind === 'json' ? modelPayloadSections(parsed.value.value).map(section => ({ ...section, cards: section.messages ? modelMessageCards(section.value,visible.value) : [] })) : []);
const rawLabel = computed(() => props.contentType.toLowerCase().includes('json') ? '原始 JSON' : props.contentType.toLowerCase().includes('event-stream') ? '原始事件流' : '原始文本');
watch([() => props.text, () => props.contentType], () => { visible.value = 30; copyStatus.value = ''; });
function fallbackCopy(text: string): boolean {
  const previous = document.activeElement; const field = document.createElement('textarea'); field.value = text; field.readOnly = true; field.style.position = 'fixed'; field.style.left = '-10000px'; document.body.append(field);
  try { field.focus(); field.select(); return document.execCommand('copy'); } finally { field.remove(); if (previous instanceof HTMLElement) previous.focus({ preventScroll: true }); }
}
async function copy(): Promise<void> {
  if (copying.value) return; const text = props.text; copying.value = true; copyStatus.value = '';
  try { let copied = false; try { if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); copied = true; } } catch { /* The user-triggered fallback also works on local HTTP dashboards. */ }
    if (!copied) copied = fallbackCopy(text); if (text === props.text) copyStatus.value = copied ? `已复制${props.complete === false ? '当前已保存的' : '完整'}原文。` : '复制失败。切换到原文视图后手动复制。';
  } catch { copyStatus.value = '复制失败。切换到原文视图后手动复制。'; } finally { copying.value = false; }
}
</script>
<template><section class="raw-payload" :aria-label="title"><header><h5>{{title}}</h5><button type="button" :disabled="copying" @click="copy">{{copying?'正在复制…':'复制原文'}}</button></header><div class="raw-payload-tabs" role="group" :aria-label="`${title}显示方式`"><button type="button" :aria-pressed="mode==='structured'" @click="mode='structured'">结构化</button><button type="button" :aria-pressed="mode==='raw'" @click="mode='raw'">{{rawLabel}}</button></div><p class="raw-payload-note">{{text.length.toLocaleString('zh-CN')}} 字符。图片 Base64 和长文本仅在页面中折叠，复制与下载保留原文。</p><p v-if="copyStatus" role="status" class="raw-payload-note">{{copyStatus}}</p>
  <textarea v-if="mode==='raw'" class="raw-payload-source" :aria-label="`${title}原文`" readonly :value="text" spellcheck="false"/>
  <div v-else-if="parsed.kind==='json'" class="raw-payload-structured"><section v-for="(section,index) in sections" :key="index" class="raw-payload-section"><h6>{{section.title}}</h6><template v-if="section.messages && section.cards.length"><article v-for="(card,cardIndex) in section.cards" :key="cardIndex" class="raw-message-card"><header><span>{{String(cardIndex+1).padStart(2,'0')}}</span><strong>{{card.title}}</strong></header><p v-if="card.metadata.length" class="raw-message-meta">{{card.metadata.join(' · ')}}</p><div class="raw-message-blocks"><template v-for="(block,blockIndex) in card.blocks" :key="blockIndex"><RawModelJsonValue v-if="block.kind==='text'" :value="block.text"/><RawModelJsonValue v-else :value="block.value" :label="block.label" :expanded-by-default="!block.collapsed"/></template></div><RawModelJsonValue v-if="card.extra" :value="card.extra" label="其他消息字段" :expanded-by-default="false"/></article><button v-if="Array.isArray(section.value)&&section.value.length>visible" type="button" @click="visible+=30">继续显示 {{Math.min(30,section.value.length-visible)}} 条消息（剩余 {{section.value.length-visible}} 条）</button></template><RawModelJsonValue v-else :value="section.value" :expanded-by-default="section.title==='系统指令'"/></section></div>
  <div v-else-if="parsed.kind==='events'" class="raw-payload-structured"><p class="raw-payload-note">{{parsed.events.length}} 个已保存事件。{{parsed.unparsed?'部分流片段还未构成完整事件，可在原始事件流中查看。':''}}</p><RawModelJsonValue v-for="event in parsed.events.slice(0,visible)" :key="event.id" :value="event.value" :label="`${Number(event.id)+1} · ${event.event}`" :expanded-by-default="false"/><button v-if="visible<parsed.events.length" type="button" @click="visible+=30">继续显示 {{Math.min(30,parsed.events.length-visible)}} 个事件</button></div>
  <div v-else class="raw-payload-structured"><p v-if="parsed.reason==='invalid_json'" class="raw-payload-note">当前内容不是完整 JSON。原文已保留，可能仍在写入。</p><p v-else-if="parsed.reason==='deep_json'" class="raw-payload-note">此 JSON 层级较深。切换到原始 JSON 查看完整结构。</p><RawModelJsonValue :value="text"/></div>
</section></template>
<style scoped>
.raw-payload{display:grid;gap:11px;min-width:0}.raw-payload>header,.raw-message-card>header{display:flex;align-items:center;justify-content:space-between;gap:12px}.raw-payload h5{font-size:13px;margin:0}.raw-payload button{font-size:11px;padding:5px 9px;background:var(--surface);justify-self:start}.raw-payload-tabs{display:flex;gap:6px;flex-wrap:wrap}.raw-payload-tabs>button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent-ink)}.raw-payload-note,.raw-message-meta{margin:0;color:var(--muted);font-size:11px;line-height:1.8;overflow-wrap:anywhere}.raw-payload-source{width:100%;min-height:360px;max-height:650px;resize:vertical;white-space:pre;overflow:auto;font:11px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace;padding:12px;background:var(--surface-soft);border:1px solid var(--line);border-radius:6px;color:var(--ink);box-sizing:border-box}.raw-payload-structured{display:grid;gap:15px;padding:14px;border:1px solid var(--line);border-radius:7px;background:var(--surface-soft);min-width:0}.raw-payload-section{min-width:0;display:grid;gap:10px}.raw-payload-section>h6{font-size:12px;margin:0}.raw-message-card{border:1px solid var(--line);border-radius:6px;background:var(--surface);padding:13px;display:grid;gap:10px;min-width:0}.raw-message-card>header{justify-content:flex-start;align-items:baseline}.raw-message-card>header>span{font-size:10px;color:var(--accent-ink)}.raw-message-card>header>strong{font-size:12px}.raw-message-blocks{display:grid;gap:10px;min-width:0}@media(max-width:600px){.raw-payload-structured{padding:10px}.raw-message-card{padding:10px}.raw-payload-source{min-height:300px}}
</style>
